// ======================================================================
// OUTPUT
// ======================================================================

return [
    {
        json: {
            node: "Node 19 - Neuro-Symbolic Security Assessment Report Generator",
            version: "1.0",
            generated_at: generatedAt,
            era_available: !!era,
